window.LAB_ITEMS = {"version":1,"lab":1,"course":"Phonetics","title":"Phonetics Playground","zodiac":{"index":1,"animal":"rat","label":"Rat"},"unit":{"one":"Trail","many":"trails"},"grading":{"total":30,"full_threshold":20,"full_score":100,"partial_score":50,"zero_score":0,"full_points":2,"partial_points":1,"alt_credit":0.5,"round":"up"},"legs":[{"id":"mb","n":1,"title":"Morpheme Builder","accent":"amber","subtitle":"Break familiar words into meaningful units","concept":"A <b>morpheme</b> is the smallest unit of language that carries meaning.","prompt":"How many morphemes are in this word?","choices":[1,2,3,4,5],"items":[{"id":"mb01","type":"count","word":"jumped","audio":null,"answer":2,"chips":[{"text":"jump","role":"root","gloss":"the action"},{"text":"-ed","role":"suffix","gloss":"past tense"}],"explain":"The root <b>jump</b> carries the action, and <b>-ed</b> adds the meaning “already happened.” Two pieces, each carrying meaning, so two morphemes.","note":null,"accept":{},"miss":{"1":"One is the count for a word you cannot break down at all. Here you can lift <b>-ed</b> off and still be left with a real word, <b>jump</b>.","3":"Three would mean a third meaningful piece. There is nothing left after <b>jump</b> and <b>-ed</b>."}},{"id":"mb02","type":"count","word":"jumping","audio":null,"answer":2,"chips":[{"text":"jump","role":"root","gloss":"the action"},{"text":"-ing","role":"suffix","gloss":"in progress"}],"explain":"Same root, different ending. <b>-ing</b> adds the meaning “in progress,” so <b>jumping</b> has two morphemes, exactly like <b>jumped</b>.","note":null,"accept":{},"miss":{"1":"The ending carries meaning too. Take <b>-ing</b> away and <b>jump</b> is still a word, so <b>-ing</b> is a morpheme of its own."}},{"id":"mb03","type":"count","word":"jumpers","audio":null,"answer":3,"chips":[{"text":"jump","role":"root","gloss":"the action"},{"text":"-er","role":"suffix","gloss":"one who does it"},{"text":"-s","role":"suffix","gloss":"more than one"}],"explain":"Two endings stack onto one root. <b>-er</b> turns an action into a person who does it, and <b>-s</b> makes that person plural. Three meaningful pieces.","note":null,"accept":{},"miss":{"2":"Look for a second ending. After <b>jump</b> there is <b>-er</b> <i>and</i> <b>-s</b>, and each one changes the meaning on its own."}},{"id":"mb04","type":"count","word":"suddenly","audio":null,"answer":2,"chips":[{"text":"sudden","role":"root","gloss":"quick and unexpected"},{"text":"-ly","role":"suffix","gloss":"turns it into how something happens"}],"explain":"<b>-ly</b> changes an adjective into an adverb, which is a change in meaning, so it counts. <b>Sudden</b> plus <b>-ly</b> is two morphemes.","note":null,"accept":{},"miss":{"3":"It is tempting to split <b>sudden</b> further, but <b>sud</b> and <b>den</b> are not pieces that carry the meaning of <b>sudden</b>. A morpheme has to mean something."}},{"id":"mb05","type":"count","word":"undo","audio":null,"answer":2,"chips":[{"text":"un-","role":"prefix","gloss":"reverse it"},{"text":"do","role":"root","gloss":"the action"}],"explain":"Morphemes are not always endings. <b>un-</b> is a prefix that reverses the meaning of whatever follows it, so <b>undo</b> is two morphemes.","note":null,"accept":{},"miss":{"1":"Check the front of the word as well as the back. <b>un-</b> adds meaning at the start of the word, the way <b>-ed</b> does at the end of <b>jumped</b>."}},{"id":"mb06","type":"count","word":"better","audio":null,"answer":1,"chips":[{"text":"better","role":"root","gloss":"the whole word is one unit"}],"explain":"<b>Better</b> looks like it ends in <b>-er</b>, the way <b>taller</b> is <b>tall</b> plus <b>-er</b>, “more tall.” But <b>better</b> does not mean “more bet,” so there is no root to split the <b>-er</b> from. It counts as one morpheme.","note":"Some books count <b>better</b> as two morphemes: <b>good</b> plus the meaning “more,” folded into one word instead of spelled out. This course counts the pieces you can point at.","accept":{"2":"You are seeing the <b>-er</b> at the end, and that instinct is right most of the time. Try the test that works for <b>taller</b>: take the ending off and see whether a meaningful word is left behind. <b>Tall</b> works. <b>Bett</b> does not. So <b>better</b> counts as one."},"miss":{"3":"There is no third piece here. <b>Better</b> does not come apart into more than two, however you look at it."}},{"id":"mb07","type":"count","word":"preheat","audio":null,"answer":2,"chips":[{"text":"pre-","role":"prefix","gloss":"before"},{"text":"heat","role":"root","gloss":"the action"}],"explain":"<b>pre-</b> means before, and it attaches to the front of a word that can stand alone. Two pieces, two morphemes.","note":null,"accept":{},"miss":{"1":"<b>Heat</b> is a word by itself, and <b>pre-</b> changes what it means. That is two meaningful pieces."}},{"id":"mb08","type":"count","word":"undercooked","audio":null,"answer":3,"chips":[{"text":"under-","role":"prefix","gloss":"not enough, below"},{"text":"cook","role":"root","gloss":"the action"},{"text":"-ed","role":"suffix","gloss":"past tense"}],"explain":"A prefix and a suffix on the same root. <b>under-</b> means not enough, <b>cook</b> is the action, and <b>-ed</b> puts it in the past. Three morphemes.","note":null,"accept":{},"miss":{"2":"Check both ends of the word. There is something added at the front <i>and</i> something added at the back."}},{"id":"mb09","type":"count","word":"supernatural","audio":null,"answer":3,"chips":[{"text":"super-","role":"prefix","gloss":"above, beyond"},{"text":"natur","role":"root","gloss":"the natural world"},{"text":"-al","role":"suffix","gloss":"turns it into a describing word"}],"explain":"<b>super-</b> means beyond, <b>natur</b> is the root you also see in <b>nature</b> and <b>natural</b>, and <b>-al</b> makes it a describing word. Three morphemes.","note":"The root is spelled <b>natur</b> here rather than <b>nature</b>. Spelling shifts a little when endings attach, and that does not change the count.","accept":{},"miss":{"2":"There are three pieces, not two. Beyond the prefix, <b>natural</b> is itself <b>natur</b> plus <b>-al</b>.","4":"Four would need one more meaningful piece. <b>natur</b> does not split any further into parts that mean something."}},{"id":"mb10","type":"count","word":"disagreements","audio":null,"answer":4,"chips":[{"text":"dis-","role":"prefix","gloss":"not, the opposite of"},{"text":"agree","role":"root","gloss":"the action"},{"text":"-ment","role":"suffix","gloss":"turns an action into a thing"},{"text":"-s","role":"suffix","gloss":"more than one"}],"explain":"The longest one in this set. <b>dis-</b> reverses it, <b>agree</b> is the action, <b>-ment</b> turns the action into a thing you can count, and <b>-s</b> makes it plural. Four morphemes.","note":null,"accept":{},"miss":{"3":"You found three of the four. Peel them off one at a time from the outside in: <b>-s</b>, then <b>-ment</b>, then <b>dis-</b>, and <b>agree</b> is what remains."}}]},{"id":"mp","n":2,"title":"Minimal Pair Detective","accent":"indigo","subtitle":"Decide whether two words differ by exactly one phoneme","concept":"A <b>minimal pair</b> is two words that differ by only one phoneme, where that one sound difference changes the meaning.","audio_note":"<b>Tap any symbol to hear it.</b> A consonant is hard to hear on its own, so most of them are recorded with a vowel after: /p/ plays as <i>pa</i>, /s/ as <i>sa</i>. The vowel is only there to carry the sound, so listen to the front of the syllable.","prompt":"Do these two words form a minimal pair?","choices":["Minimal pair","Not a minimal pair"],"items":[{"id":"mp01","type":"boolean","a":{"word":"cat","ipa":["k","æ","t"],"audio":"w_cat"},"b":{"word":"hat","ipa":["h","æ","t"],"audio":"w_hat"},"answer":true,"aligned":true,"diffs":[0],"explain":"Only the first sound changes, /k/ to /h/, and that one change gives you a different word. That is exactly what a minimal pair is.","note":null,"accept":{},"miss":{"false":"Compare them sound by sound. The vowel matches and the last sound matches. Only the first position differs."}},{"id":"mp02","type":"boolean","a":{"word":"cat","ipa":["k","æ","t"],"audio":"w_cat"},"b":{"word":"sad","ipa":["s","æ","d"],"audio":"w_sad"},"answer":false,"aligned":true,"diffs":[0,2],"explain":"Two positions differ, the first (/k/ against /s/) and the last (/t/ against /d/). A minimal pair allows exactly one difference, so this is not one.","note":null,"accept":{},"miss":{"true":"The vowel is the same in both, which makes them feel close. Check the ends too: /t/ and /d/ are different sounds."}},{"id":"mp03","type":"boolean","a":{"word":"cat","ipa":["k","æ","t"],"audio":"w_cat"},"b":{"word":"dog","ipa":["d","ɔ","g"],"audio":"w_dog"},"answer":false,"aligned":true,"diffs":[0,1,2],"explain":"All three positions differ: /k/ against /d/, /æ/ against /ɔ/, and /t/ against /g/. Two words can be the same length and still share nothing.","note":"<b>/ɔ/</b> is the rounded back vowel this course uses for <b>dog</b>, <b>caught</b> and <b>bought</b>. It sits close to <b>/ɑ/</b>, the unrounded vowel in <b>father</b> and <b>cot</b>, and many American speakers no longer keep the two apart. If <b>cot</b> and <b>caught</b> sound identical when you say them, you have that merger, and you may hear /dɑg/ where this lab writes /dɔg/.","accept":{},"miss":{"true":"Same number of sounds is not the same as one difference. Line them up and check each position separately."}},{"id":"mp04","type":"boolean","a":{"word":"sip","ipa":["s","ɪ","p"],"audio":"w_sip"},"b":{"word":"zip","ipa":["z","ɪ","p"],"audio":"w_zip"},"answer":true,"aligned":true,"diffs":[0],"explain":"/s/ and /z/ are made in the same place and in the same way. They differ only in <b>voicing</b>: the vocal folds vibrate for /z/ but not for /s/.","note":"Two sounds can feel almost identical and still be separate phonemes, because swapping one for the other changes the word.","accept":{},"miss":{"false":"Say them with your fingers on your throat. /z/ buzzes and /s/ does not. Different sound, same position, everything else matching."}},{"id":"mp05","type":"boolean","a":{"word":"sun","ipa":["s","ʌ","n"],"audio":"w_sun"},"b":{"word":"shoe","ipa":["ʃ","u"],"audio":"w_shoe"},"answer":false,"aligned":false,"diffs":null,"explain":"These words do not even have the same number of sounds. <b>Sun</b> has three, /s ʌ n/, and <b>shoe</b> has two, /ʃ u/. No single swap can turn one into the other, so they cannot be a minimal pair.","note":"Length is the fastest first check. If two words have different numbers of phonemes, you can rule out a minimal pair without comparing anything else.","accept":{},"miss":{"true":"Count the sounds in each first. Three against two means at least one position has no partner to compare with."}},{"id":"mp06","type":"boolean","a":{"word":"but","ipa":["b","ʌ","t"],"audio":"w_but"},"b":{"word":"bat","ipa":["b","æ","t"],"audio":"w_bat"},"answer":true,"aligned":true,"diffs":[1],"explain":"The consonants on both ends match. Only the vowel changes, /ʌ/ to /æ/, and the word changes with it. Minimal pairs are not only about consonants.","note":null,"accept":{},"miss":{"false":"Vowels count too. The only thing separating these two words is the sound in the middle."}},{"id":"mp07","type":"boolean","a":{"word":"bee","ipa":["b","i"],"audio":"w_bee"},"b":{"word":"me","ipa":["m","i"],"audio":"w_me"},"answer":true,"aligned":true,"diffs":[0],"explain":"Two sounds each, and only the first differs: /b/ against /m/. Short words make minimal pairs easy to see.","note":null,"accept":{},"miss":{"false":"Both words are just a consonant plus /i/. Compare the two consonants."}},{"id":"mp08","type":"boolean","a":{"word":"bird","ipa":["b","ɝ","d"],"audio":"w_bird"},"b":{"word":"burp","ipa":["b","ɝ","p"],"audio":"w_burp"},"answer":true,"aligned":true,"diffs":[2],"explain":"The spelling looks different, <b>ir</b> against <b>ur</b>, but both spell the same vowel /ɝ/. Only the final sound changes, /d/ to /p/.","note":"A good reminder that this activity is about sounds, not letters. Two different spellings can be the same phoneme.","accept":{},"miss":{"false":"Do not let <b>ir</b> and <b>ur</b> fool you. Say the words out loud: the middle is identical. The difference is at the end."}},{"id":"mp09","type":"boolean","a":{"word":"sake","ipa":["s","eɪ","k"],"audio":"w_sake"},"b":{"word":"shave","ipa":["ʃ","eɪ","v"],"audio":"w_shave"},"answer":false,"aligned":true,"diffs":[0,2],"explain":"Two positions differ. At the start, /s/ against /ʃ/, and at the end, /k/ against /v/. The vowel /eɪ/ is the only thing they share.","note":"The trap is the spelling <b>sh</b>. It looks like <b>s</b> with an <b>h</b> added, but it spells /ʃ/, a single phoneme of its own.","accept":{},"miss":{"true":"You probably counted <b>sh</b> as a version of /s/, which would leave only the ending as a difference. It is not: /ʃ/ is its own phoneme, so this pair differs in two places."}},{"id":"mp10","type":"boolean","a":{"word":"math","ipa":["m","æ","θ"],"audio":"w_math"},"b":{"word":"myth","ipa":["m","ɪ","θ"],"audio":"w_myth"},"answer":true,"aligned":true,"diffs":[1],"explain":"Both start with /m/ and end with /θ/. Only the vowel changes, /æ/ to /ɪ/, so this is a minimal pair.","note":null,"accept":{},"miss":{"false":"The spellings <b>a</b> and <b>y</b> look unrelated, but they are both just spelling the vowel. Everything around the vowel is identical."}}]},{"id":"pc","n":3,"title":"Phoneme Counter","accent":"coral","subtitle":"Count speech sounds rather than letters","concept":"A <b>phoneme</b> is a speech sound that can distinguish meaning. Count the sounds you make, not the letters you write.","prompt":"How many phonemes are in this word?","choices":[1,2,3,4,5],"items":[{"id":"pc01","type":"count","word":"eye","audio":"w_eye","answer":1,"chips":[{"letters":"eye","ipa":"ɑɪ","slug":"ay"}],"letters":3,"explain":"Three letters, one sound. /ɑɪ/ is a diphthong: your tongue glides from one vowel position toward another, but the whole glide counts as a single phoneme.","note":"The bar joining the two symbols in /ɑɪ/ marks them as one sound. You will see the same bar on every diphthong: /eɪ/, /oʊ/, /ɑʊ/ and /ɔɪ/.","accept":{"2":"You heard the glide as two vowel targets, /ɑ/ moving toward /ɪ/, which is exactly what your mouth does. That is why the two symbols are there. The bar joining them is what tells you to count the whole glide as <b>one</b>."},"miss":{"3":"You counted the letters e, y, e. None of them makes a separate sound here. The whole spelling produces one gliding vowel.","4":"There is one gliding vowel in this word and nothing else at all."}},{"id":"pc02","type":"count","word":"cat","audio":"w_cat","answer":3,"chips":[{"letters":"c","ipa":"k","slug":"k"},{"letters":"a","ipa":"æ","slug":"ae"},{"letters":"t","ipa":"t","slug":"t"}],"letters":3,"explain":"Three letters, three sounds, one for one. The only thing to notice is that the letter <b>c</b> is spelling the sound /k/.","note":null,"accept":{},"miss":{}},{"id":"pc03","type":"count","word":"dog","audio":"w_dog","answer":3,"chips":[{"letters":"d","ipa":"d","slug":"d"},{"letters":"o","ipa":"ɔ","slug":"ao"},{"letters":"g","ipa":"g","slug":"g"}],"letters":3,"explain":"Another one for one word: /d/ /ɔ/ /g/. Three letters, three phonemes.","note":null,"accept":{},"miss":{}},{"id":"pc04","type":"count","word":"shoe","audio":"w_shoe","answer":2,"chips":[{"letters":"sh","ipa":"ʃ","slug":"sh"},{"letters":"oe","ipa":"u","slug":"uw"}],"letters":4,"explain":"Four letters, two sounds. <b>sh</b> spells the single phoneme /ʃ/, and <b>oe</b> spells the single vowel /u/.","note":"Letter pairs that spell one sound are called digraphs. English is full of them.","accept":{},"miss":{"3":"Check whether <b>oe</b> is making one sound or two. Say the word slowly: after /ʃ/ there is a single vowel, nothing more.","4":"You counted the letters s, h, o, e. Two of those pairs each make one sound."}},{"id":"pc05","type":"count","word":"ship","audio":"w_ship","answer":3,"chips":[{"letters":"sh","ipa":"ʃ","slug":"sh"},{"letters":"i","ipa":"ɪ","slug":"ih"},{"letters":"p","ipa":"p","slug":"p"}],"letters":4,"explain":"Four letters, three sounds. <b>sh</b> is one phoneme, /ʃ/, then /ɪ/ and /p/.","note":null,"accept":{},"miss":{"4":"The <b>s</b> and the <b>h</b> are not making separate sounds. Together they spell /ʃ/, which is a single phoneme."}},{"id":"pc06","type":"count","word":"chair","audio":"w_chair","answer":3,"chips":[{"letters":"ch","ipa":"tʃ","slug":"ch"},{"letters":"ai","ipa":"ɛ","slug":"eh"},{"letters":"r","ipa":"ɹ","slug":"r"}],"letters":5,"explain":"Five letters, three sounds. <b>ch</b> spells /tʃ/, <b>ai</b> spells /ɛ/, and <b>r</b> spells /ɹ/.","note":"<b>ch</b> spells one phoneme, /tʃ/. It is an <b>affricate</b>: the air is stopped completely, then let out through a narrow gap with a hiss, all in one movement. English has one other affricate, /dʒ/, spelled <b>j</b> in <b>jump</b> and <b>g</b> in <b>giraffe</b>. It counts as one sound too.","accept":{"4":"You have counted /tʃ/ as two sounds. It is an easy one to split, because it is written with two symbols and it really does start like /t/ and end like /ʃ/. The bar joining them means count it as <b>one</b>. Everything else in the word you counted correctly."},"miss":{"5":"You counted the letters. Two of those letter groups, <b>ch</b> and <b>ai</b>, each make one sound."}},{"id":"pc07","type":"count","word":"think","audio":"w_think","answer":4,"chips":[{"letters":"th","ipa":"θ","slug":"th"},{"letters":"i","ipa":"ɪ","slug":"ih"},{"letters":"n","ipa":"ŋ","slug":"ng"},{"letters":"k","ipa":"k","slug":"k"}],"letters":5,"explain":"Five letters, four sounds. <b>th</b> spells the single phoneme /θ/. The <b>n</b> before <b>k</b> is pronounced /ŋ/, the sound at the end of <b>sing</b>.","note":"A letter can spell a different sound depending on what follows it.","accept":{},"miss":{"5":"The <b>t</b> and <b>h</b> are not two sounds. Together they spell /θ/, the sound you make with your tongue between your teeth.","3":"There are four: /θ/, /ɪ/, /ŋ/, and /k/. The /k/ at the end is its own sound."}},{"id":"pc08","type":"count","word":"black","audio":"w_black","answer":4,"chips":[{"letters":"b","ipa":"b","slug":"b"},{"letters":"l","ipa":"l","slug":"l"},{"letters":"a","ipa":"æ","slug":"ae"},{"letters":"ck","ipa":"k","slug":"k"}],"letters":5,"explain":"Five letters, four sounds. The consonant cluster <b>bl</b> is two separate phonemes, /b/ and /l/, while <b>ck</b> at the end is two letters spelling one, /k/.","note":"A cluster and a digraph look similar on the page and behave in opposite ways.","accept":{},"miss":{"5":"The <b>c</b> and <b>k</b> at the end make a single /k/. You do not say the sound twice.","3":"The <b>bl</b> at the front is two sounds, not one. You can hear /b/ and then /l/."}},{"id":"pc09","type":"count","word":"cheese","audio":"w_cheese","answer":3,"chips":[{"letters":"ch","ipa":"tʃ","slug":"ch"},{"letters":"ee","ipa":"i","slug":"iy"},{"letters":"se","ipa":"z","slug":"z"}],"letters":6,"explain":"Six letters, three sounds. <b>ch</b> spells /tʃ/, <b>ee</b> spells /i/, and the final <b>s</b> is pronounced /z/ with a silent <b>e</b> after it.","note":"A silent letter makes no sound, so it never adds to the count.","accept":{"4":"There are two ways you could have arrived at 4, so check which one it was.<br><br>If you counted /tʃ/ as two sounds, the bar joining the symbols means count it as one.<br><br>If instead you counted the final <b>e</b>, that letter is silent. <b>se</b> spells a single /z/."},"miss":{"5":"You are close to counting letters. Three of the six do no work on their own: the <b>h</b> belongs to <b>ch</b>, one of the <b>e</b>s belongs to <b>ee</b>, and the final <b>e</b> is silent."}},{"id":"pc10","type":"count","word":"brush","audio":"w_brush","answer":4,"chips":[{"letters":"b","ipa":"b","slug":"b"},{"letters":"r","ipa":"ɹ","slug":"r"},{"letters":"u","ipa":"ʌ","slug":"ah"},{"letters":"sh","ipa":"ʃ","slug":"sh"}],"letters":5,"explain":"Five letters, four sounds. <b>br</b> is a cluster, so /b/ and /ɹ/ are separate, and <b>sh</b> is a digraph spelling the single phoneme /ʃ/.","note":"This word has both patterns in it, a cluster at the front and a digraph at the back.","accept":{},"miss":{"5":"The <b>sh</b> at the end is one sound, as it was in <b>ship</b> and <b>shoe</b>.","3":"The <b>br</b> at the front is two sounds. Say it slowly and you can separate /b/ from /ɹ/."}}]}]};
